targets.query:
from(bucket: "luxmon")
  |> range(start: -7d)
  |> filter(fn: (r) => r._measurement == "luxmon_register" and r.name == "soc" and r._field == "value")
  |> last()
  |> group()
  |> map(fn: (r) => ({
      _time: r._time,
      "Since last point": float(v: int(v: now()) - int(v: r._time)) / 1000000000.0,
      "Status": float(v: int(v: now()) - int(v: r._time)) / 1000000000.0,
  }))

import "internal/debug"

// I = P / V per MPPT, per window. Null when either input is missing (gap);
// 0 A when the string voltage is ~0 (string dark / disconnected).
from(bucket: "luxmon")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "luxmon_register" and (r.name == "pv1_power" or r.name == "pv1_voltage" or r.name == "pv2_power" or r.name == "pv2_voltage") and r._field == "value")
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: true)
  |> keep(columns: ["_time", "_value", "name"])
  |> group()
  |> pivot(rowKey: ["_time"], columnKey: ["name"], valueColumn: "_value")
  |> map(fn: (r) => ({
      _time: r._time,
      PV1: if exists r.pv1_power and exists r.pv1_voltage then (if r.pv1_voltage > 1.0 then r.pv1_power / r.pv1_voltage else 0.0) else debug.null(type: "float"),
      PV2: if exists r.pv2_power and exists r.pv2_voltage then (if r.pv2_voltage > 1.0 then r.pv2_power / r.pv2_voltage else 0.0) else debug.null(type: "float"),
  }))
  |> sort(columns: ["_time"])
